# Generated by build.py from recipe.yml for recipe ldap-search-with-a-filter-and-scope. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site/.surl/ldap' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/.surl/ldap/directory.ldif'), "dn: dc=example,dc=com`nobjectClass: domain`ndc: example`n`ndn: ou=people,dc=example,dc=com`nobjectClass: organizationalUnit`nou: people`n`ndn: cn=alice,ou=people,dc=example,dc=com`nobjectClass: person`ncn: alice`nsn: Liddell`nmail: alice@example.com`n`ndn: cn=bob,ou=people,dc=example,dc=com`nobjectClass: person`ncn: bob`nsn: Builder`nmail: bob@example.com`n`ndn: ou=groups,dc=example,dc=com`nobjectClass: organizationalUnit`nou: groups`n`ndn: cn=staff,ou=groups,dc=example,dc=com`nobjectClass: groupOfNames`ncn: staff`nmember: cn=alice,ou=people,dc=example,dc=com`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--allow-anonymous', 'ldap://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -u : "ldap://127.0.0.1:8080/ou=people,dc=example,dc=com?mail?one?(sn=B*)" } finally { Stop-Process $server0 }
